"""Append-only research registry + auto-generated human index.

Problem this solves: every backtest/probe script in this repo used to write
its own one-off report file (docs/research/*.md, chart_predictor/data/setups/
report_<hash>.json, scratch /tmp files) with no central place listing what
was tried, when, and with what verdict. Finding "did we already test X" meant
grepping prose docs by hand.

Usage from any backtest/probe script, right after it has a result:

    from scripts.research.registry import log_experiment
    log_experiment(
        track="coin",                      # "coin" or "stock" -- no other values
        phase="P9-F",                       # short id matching the prose doc section,
                                             # or a new slug if there is no prose doc
        title="order_block 20-symbol + fvg_fill confluence (two-track)",
        method="aggressive/balanced/conservative confluence filter on order_block "
               "and fvg_fill zones; 1->5/20 symbol staged check",
        scope="20 symbols (track A) / 5 symbols (track B), 84-day dev window, 2R",
        headline_metric="hit rate flat 12-33% across all confluence tiers",
        verdict="REJECT",                   # PASS / REJECT / VALIDATION_REQUIRED /
                                             # BLOCKED / NOT_EVALUABLE
        bar="coin target-first hit rate >=80%, n>=200",
        artifacts=["chart_predictor/setups.py (order_block_confluence_*)"],
        doc_ref="docs/chart_predictor/rounds.md",
        note="confluence tiers shrink sample, never raise hit rate",
    )

This appends one line to docs/research/registry.jsonl and regenerates
docs/research/INDEX.md so the index is always in sync with the data.
Never hand-edit INDEX.md -- it is overwritten on the next log_experiment()
or rebuild-index call. The jsonl file is append-only and git-tracked; it is
the source of truth, INDEX.md is a derived view.

Rebuild the index without adding a row (e.g. after backfilling jsonl rows
some other way):
    python3 scripts/research/registry.py rebuild-index

Browse from the shell:
    python3 scripts/research/registry.py list
    python3 scripts/research/registry.py list --track coin
    python3 scripts/research/registry.py list --verdict REJECT
    python3 scripts/research/registry.py show 17
"""
from __future__ import annotations
import argparse
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
REGISTRY_PATH = ROOT / "docs/research/registry.jsonl"
INDEX_PATH = ROOT / "docs/research/INDEX.md"

TRACKS = ("coin", "stock")
VERDICTS = ("PASS", "REJECT", "VALIDATION_REQUIRED", "BLOCKED", "NOT_EVALUABLE")


def _load() -> list[dict]:
    if not REGISTRY_PATH.exists():
        return []
    rows = []
    for line in REGISTRY_PATH.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if line:
            rows.append(json.loads(line))
    return rows


def log_experiment(*, track, phase, title, method, scope, headline_metric, verdict,
                    bar=None, artifacts=None, doc_ref=None, note=None, ts=None,
                    rebuild=True) -> int:
    """Append one experiment row. Returns its assigned id.

    rebuild=False skips regenerating INDEX.md -- only use this for bulk
    backfills that call render_index() once at the end themselves.
    """
    if track not in TRACKS:
        raise ValueError(f"track must be one of {TRACKS}, got {track!r}")
    if verdict not in VERDICTS:
        raise ValueError(f"verdict must be one of {VERDICTS}, got {verdict!r}")
    rows = _load()
    row = {
        "id": (rows[-1]["id"] + 1) if rows else 1,
        "ts": ts or datetime.now(timezone.utc).date().isoformat(),
        "track": track,
        "phase": phase,
        "title": title,
        "method": method,
        "scope": scope,
        "headline_metric": headline_metric,
        "verdict": verdict,
        "bar": bar,
        "artifacts": list(artifacts or []),
        "doc_ref": doc_ref,
        "note": note,
    }
    REGISTRY_PATH.parent.mkdir(parents=True, exist_ok=True)
    with REGISTRY_PATH.open("a", encoding="utf-8") as f:
        f.write(json.dumps(row, ensure_ascii=False) + "\n")
    if rebuild:
        render_index()
    return row["id"]


def render_index() -> None:
    rows = _load()
    today = datetime.now(timezone.utc).date().isoformat()
    lines = [
        "# Research Index",
        "",
        "Auto-generated by `scripts/research/registry.py` from `docs/research/registry.jsonl`.",
        "**Never hand-edit this file** -- it is overwritten on the next `log_experiment()` "
        "or `rebuild-index` call. Edit the jsonl, or call `log_experiment()`, instead.",
        "",
        f"{len(rows)} logged experiments as of {today}. Full detail for one row: "
        "`python3 scripts/research/registry.py show <id>`.",
        "",
    ]
    verdict_counts = {}
    for r in rows:
        verdict_counts[r["verdict"]] = verdict_counts.get(r["verdict"], 0) + 1
    if rows:
        lines.append("Verdict counts: " + ", ".join(f"{k}={v}" for k, v in sorted(verdict_counts.items())))
        lines.append("")
    for track in TRACKS:
        trows = [r for r in rows if r["track"] == track]
        if not trows:
            continue
        lines.append(f"## {track} ({len(trows)})")
        lines.append("")
        lines.append("| id | date | phase | title | verdict | headline |")
        lines.append("|---:|---|---|---|---|---|")
        for r in trows:
            title = r["title"].replace("|", "/")
            headline = r["headline_metric"].replace("|", "/")
            doc = r.get("doc_ref")
            title_cell = f"[{title}]({doc})" if doc else title
            lines.append(f"| {r['id']} | {r['ts']} | {r['phase']} | {title_cell} | {r['verdict']} | {headline} |")
        lines.append("")
    INDEX_PATH.write_text("\n".join(lines), encoding="utf-8")


def _cmd_list(args) -> None:
    for r in _load():
        if args.track and r["track"] != args.track:
            continue
        if args.verdict and r["verdict"] != args.verdict:
            continue
        print(f"{r['id']:>3}  {r['ts']}  {r['track']:5}  {r['phase']:8}  {r['verdict']:20}  {r['title']}")


def _cmd_show(args) -> None:
    rows = _load()
    match = next((r for r in rows if r["id"] == args.id), None)
    if match is None:
        print(f"no row with id {args.id}", file=sys.stderr)
        sys.exit(1)
    print(json.dumps(match, ensure_ascii=False, indent=2))


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="command")
    sub.add_parser("rebuild-index")
    p_list = sub.add_parser("list")
    p_list.add_argument("--track", choices=TRACKS)
    p_list.add_argument("--verdict", choices=VERDICTS)
    p_show = sub.add_parser("show")
    p_show.add_argument("id", type=int)
    args = parser.parse_args()
    if args.command == "rebuild-index":
        render_index()
        print(f"wrote {INDEX_PATH}")
    elif args.command == "list":
        _cmd_list(args)
    elif args.command == "show":
        _cmd_show(args)
    else:
        parser.print_help()


if __name__ == "__main__":
    main()
